object EnvironmentMapping extends ValueMapping[IO] {
  val schema = schema"""
    type Query { nested: Nested! }
    type Nested { sum(x: Int!, y: Int!): Int! }
  """
  val QueryType = schema.ref("Query")
  val NestedType = schema.ref("Nested")

  // CursorField reads the values the elaborator stashed in the env
  def sum(c: Cursor): Result[Int] =
    (for { x <- c.env[Int]("x"); y <- c.env[Int]("y") } yield x + y).toResult("Missing argument")

  override val selectElaborator = SelectElaborator {
    case (NestedType, "sum", List(Binding("x", IntValue(x)), Binding("y", IntValue(y)))) =>
      Elab.env("x" -> x, "y" -> y)
  }
}

