import grackle.Query._
import grackle.QueryCompiler._
import grackle.Value._

override val selectElaborator = SelectElaborator {
  // characters(offset, limit) -> Limit(.., Offset(.., child))
  case (QueryType, "characters",
        List(Binding("offset", IntValue(offset)), Binding("limit", IntValue(limit)))) =>
    Elab.transformChild(child => Limit(limit, Offset(offset, child)))

  // numberOfFriends -> replace selection set with a Count over friends
  case (CharacterType | HumanType | DroidType, "numberOfFriends", _) =>
    Elab.transformChild(_ => Count(Select("friends")))
}

import grackle._
import grackle.Query._
import grackle.QueryCompiler._

object PreserveArgsElaborator extends SelectElaborator {
  case class Preserved(args: List[Binding], directives: List[Directive])

  override def transform(query: Query): Elab[Query] = query match {
    case UntypedSelect(fieldName, _, _, _, _) =>
      for {
        t         <- super.transform(query)
        preserved <- Elab.envE[Preserved]("preserved")
      } yield subst(t, fieldName, preserved)
    case other => super.transform(other)
  }

  def select(ref: TypeRef, name: String, args: List[Binding],
             directives: List[Directive]): Elab[Unit] =
    Elab.env("preserved", Preserved(args, directives))
}
